   package com.android.tools.lint.checks

   import com.android.resources.ResourceFolderType
   import com.android.tools.lint.detector.api.*
   import org.w3c.dom.Attr
   import org.w3c.dom.Element
   import java.util.regex.Pattern

   class ResourceCycleDetector : ResourceXmlDetector() {
       // Graph: source -> set of targets
       private val graph = mutableMapOf<String, MutableSet<String>>()
       // Location map for reporting: resource -> location
       private val locations = mutableMapOf<String, Location>()
       // Reference locations: "source->target" -> location
       private val refLocations = mutableMapOf<String, Location>()

       companion object {
           val ISSUE = Issue.create(
               id = "ResourceCycle",
               briefDescription = "Cycle in resource definitions",
               explanation = "There should be no cycles in resource definitions as this can lead to runtime exceptions.",
               category = Category.CORRECTNESS,
               priority = 6,
               severity = Severity.ERROR,
               implementation = Implementation(
                   ResourceCycleDetector::class.java,
                   Scope.RESOURCE_FILE_SCOPE
               )
           )

           private val RESOURCE_REF_PATTERN = Pattern.compile("@(\\+)?(\\w+:)?(\\w+)/(\\w+)")
       }

       override fun getApplicableElements(): Collection<String>? = ALL

       override fun visitElement(context: XmlContext, element: Element) {
           // Determine the source resource being defined
           val sourceRes = getSourceResource(context, element) ?: return

           // Store location for the source resource definition
           if (!locations.containsKey(sourceRes)) {
               locations[sourceRes] = context.getLocation(element)
           }

           // Check all attributes for references
           val attributes = element.attributes
           for (i in 0 until attributes.length) {
               val attr = attributes.item(i) as Attr
               val value = attr.value
               if (value.contains('@')) {
                   val matcher = RESOURCE_REF_PATTERN.matcher(value)
                   while (matcher.find()) {
                       val type = matcher.group(3)
                       val name = matcher.group(4)
                       val targetRes = "$type/$name"
                       graph.getOrPut(sourceRes) { mutableSetOf() }.add(targetRes)
                       refLocations["$sourceRes->$targetRes"] = context.getLocation(attr)
                   }
               }
           }
       }

       private fun getSourceResource(context: XmlContext, element: Element): String? {
           val folderType = context.resourceFolderType ?: return null
           val tagName = element.tagName

           // For values folders, resources are defined by name attribute
           if (folderType == ResourceFolderType.VALUES) {
               // Skip root <resources> tag
               if (tagName == "resources") return null
               val name = element.getAttribute("name")
               if (name.isNotEmpty()) {
                   // Map tag name to resource type (e.g., <string> -> string, <item type="drawable"> -> drawable)
                   val type = when (tagName) {
                       "item" -> element.getAttribute("type").takeIf { it.isNotEmpty() } ?: return null
                       "declare-styleable", "attr" -> return null // Skip these for simplicity or handle appropriately
                       else -> tagName
                   }
                   return "$type/$name"
               }
               return null
           }

           // For other folders, the file itself is the resource
           // e.g., res/drawable/icon.xml -> drawable/icon
           val fileName = context.file.nameWithoutExtension
           return "$folderType/$fileName"
       }

       override fun afterCheckRootProject(context: Context) {
           detectCycles(context)
       }

       private fun detectCycles(context: Context) {
           val state = mutableMapOf<String, Int>() // 0: unvisited, 1: visiting, 2: visited
           val path = mutableListOf<String>()
           val reportedCycles = mutableSetOf<Set<String>>()

           fun dfs(node: String) {
               if (state[node] == 2) return
               if (state[node] == 1) {
                   // Cycle found
                   val cycleStart = path.indexOf(node)
                   if (cycleStart != -1) {
                       val cycleNodes = path.subList(cycleStart, path.size).toSet()
                       // Avoid duplicate reports for the same cycle
                       if (reportedCycles.add(cycleNodes)) {
                           reportCycle(context, cycleNodes.toList(), node)
                       }
                   }
                   return
               }

               state[node] = 1
               path.add(node)

               for (neighbor in graph[node].orEmpty()) {
                   dfs(neighbor)
               }

               path.removeAt(path.lastIndex)
               state[node] = 2
           }

           for (node in graph.keys) {
               if (state[node] != 2) {
                   dfs(node)
               }
           }
       }

       private fun reportCycle(context: Context, cycle: List<String>, closingNode: String) {
           // Build a readable cycle string: A -> B -> C -> A
           val cycleStr = cycle.joinToString(" -> ") + " -> ${cycle.first()}"

           // Find a location to report. Prefer the reference that closes the cycle.
           val refKey = "$closingNode->${cycle.first()}"
           val location = refLocations[refKey] ?: locations[closingNode] ?: Location.create(context.file)

           context.report(
               ISSUE,
               location,
               "Resource cycle detected: $cycleStr"
           )
       }
   }
